// OrderServiceHandler is an implementation of the hawkr.order.OrderService service.
type OrderServiceHandler interface {
	// 建立訂單
	CreateOrder(context.Context, *connect.Request[order.CreateOrderRequest]) (*connect.Response[order.CreateOrderResponse], error)
	// EXTERNAL lane RFQ 成交建單（64 號 §6.4）。
	//
	// ⛔ 不是 CreateOrder 的變體，也不是它的 lane 分支：本 RPC 刻意不走庫存協調
	//    路徑（不扣庫存、不寫 stock_tx、不鎖購物車、不進補償 worker）——站外業者
	//    的貨在站外，平台不持有可售數量。持久化仍共用同一個 TX handler。
	//    改 createOrder 加分支要動到 @Transactional 與補償路徑內的兩處，那是全平台
	//    共用的庫存寫入路徑，正是 64 號 §6.2 否決 2PC 時用的同一條理由。
	//
	// ⚠️ 只服務 EXTERNAL lane。PLATFORM lane 的 RFQ 成交走現行 CreateOrder
	//    （有真 SKU 與真庫存，賣方就是那個平台賣家）。
	//
	// 冪等鍵＝acceptance_id（orders.acceptance_id 偏唯一索引）：命令由 ai-service 的
	// outbox worker 投遞，重試必然發生；重送回既有 order_no，不建第二張。
	CreateRfqOrder(context.Context, *connect.Request[order.CreateRfqOrderRequest]) (*connect.Response[order.CreateRfqOrderResponse], error)
	// 取消訂單（僅限 PENDING_PAYMENT 狀態）
	CancelOrder(context.Context, *connect.Request[order.CancelOrderRequest]) (*connect.Response[order.CancelOrderResponse], error)
	// 查詢我的訂單列表
	GetMyOrders(context.Context, *connect.Request[order.GetMyOrdersRequest]) (*connect.Response[order.GetMyOrdersResponse], error)
	// 查詢買家各狀態訂單筆數（訂單 tab 筆數 rollup，規則見 03 §2.1「買家訂單 Tab 筆數 Rollup（SSOT）」）
	GetMyOrderStatusCounts(context.Context, *connect.Request[order.GetMyOrderStatusCountsRequest]) (*connect.Response[order.GetMyOrderStatusCountsResponse], error)
	// 查詢訂單詳情（買家視角）
	GetOrder(context.Context, *connect.Request[order.GetOrderRequest]) (*connect.Response[order.GetOrderResponse], error)
	// 確認收貨（買家手動，物流已送達後操作）
	ConfirmReceipt(context.Context, *connect.Request[order.ConfirmReceiptRequest]) (*connect.Response[order.ConfirmReceiptResponse], error)
	// 查詢賣家訂單列表
	GetSellerOrders(context.Context, *connect.Request[order.GetSellerOrdersRequest]) (*connect.Response[order.GetSellerOrdersResponse], error)
	// 查詢賣家訂單詳情
	GetSellerOrderDetail(context.Context, *connect.Request[order.GetSellerOrderDetailRequest]) (*connect.Response[order.GetSellerOrderDetailResponse], error)
	// 根據物流序號查詢訂單（shipping-service 用）
	GetOrderByShipTradeNo(context.Context, *connect.Request[order.GetOrderByShipTradeNoRequest]) (*connect.Response[order.GetOrderByShipTradeNoResponse], error)
	// 查詢訂單評論資格（review-service 用）
	GetOrderForReview(context.Context, *connect.Request[order.GetOrderForReviewRequest]) (*connect.Response[order.GetOrderForReviewResponse], error)
	// 取得物流建單所需訂單資訊（shipping-service 用）
	GetOrderForShipping(context.Context, *connect.Request[order.GetOrderForShippingRequest]) (*connect.Response[order.GetOrderForShippingResponse], error)
	// 查詢買家在各賣家的累計消費總額（buyer 模組用，會員卡清單）
	GetBuyerMerchantSummary(context.Context, *connect.Request[order.GetBuyerMerchantSummaryRequest]) (*connect.Response[order.GetBuyerMerchantSummaryResponse], error)
	// 查詢買家在特定賣家的消費紀錄（buyer 模組用，消費紀錄明細）
	GetBuyerOrdersForSeller(context.Context, *connect.Request[order.GetBuyerOrdersForSellerRequest]) (*connect.Response[order.GetBuyerOrdersForSellerResponse], error)
	// 售後用：查詢訂單詳情（含買家地址、金額、送達時間，aftersales-service 用）
	GetOrderForAfterSales(context.Context, *connect.Request[order.GetOrderForAfterSalesRequest]) (*connect.Response[order.GetOrderForAfterSalesResponse], error)
	// 售後用：內部取消訂單（CAS status IN (0,10,20)，aftersales-service 用）
	CancelOrderInternal(context.Context, *connect.Request[order.CancelOrderInternalRequest]) (*connect.Response[order.CancelOrderInternalResponse], error)
	// 賣家停權 IM 訂單關聯回填用：反查買賣雙方之間是否存在關聯訂單
	// （判準 status NOT IN (0,80)，14 號設計書 §6.5.1 路徑②，46 號 §4.4；im-service 用）
	HasOrderBetween(context.Context, *connect.Request[order.HasOrderBetweenRequest]) (*connect.Response[order.HasOrderBetweenResponse], error)
	// 即時驗證（購物車勾選時呼叫，輕量級，預設運費 Grid）
	CheckoutValidate(context.Context, *connect.Request[order.CheckoutValidateRequest]) (*connect.Response[order.CheckoutValidateResponse], error)
	// 運費精算（選配送方式 + 填地址/選門市後呼叫）
	CheckoutShippingFee(context.Context, *connect.Request[order.CheckoutShippingFeeRequest]) (*connect.Response[order.CheckoutShippingFeeResponse], error)
	// 結帳預覽（完整驗證 + 精算總額，不建單）
	CheckoutPreview(context.Context, *connect.Request[order.CheckoutPreviewRequest]) (*connect.Response[order.CheckoutPreviewResponse], error)
	// 確認結帳（建單 + 回傳付款資訊）
	CheckoutConfirm(context.Context, *connect.Request[order.CheckoutConfirmRequest]) (*connect.Response[order.CheckoutConfirmResponse], error)
	// 取得訂單付款資訊（Payment Service 內部呼叫）
	GetOrderForPayment(context.Context, *connect.Request[order.GetOrderForPaymentRequest]) (*connect.Response[order.GetOrderForPaymentResponse], error)
	// 快照付款資訊到訂單（CreatePayment 成功後由 Gateway 呼叫）
	SnapshotPaymentInfo(context.Context, *connect.Request[order.SnapshotPaymentInfoRequest]) (*connect.Response[order.SnapshotPaymentInfoResponse], error)
	// 搜尋訂單（後台）
	SearchOrders(context.Context, *connect.Request[order.SearchOrdersRequest]) (*connect.Response[order.SearchOrdersResponse], error)
	// 查詢訂單詳情（後台，含資金流水）
	GetAdminOrderDetail(context.Context, *connect.Request[order.GetAdminOrderDetailRequest]) (*connect.Response[order.GetAdminOrderDetailResponse], error)
	// 查詢賣家訂單狀態計數（gateway 用，儀表板）
	GetSellerOrderStatusCounts(context.Context, *connect.Request[order.GetSellerOrderStatusCountsRequest]) (*connect.Response[order.GetSellerOrderStatusCountsResponse], error)
	// 查詢近 N 天營收排名前 N 的賣家（gateway 推薦商家用）
	GetTopSellersByRevenue(context.Context, *connect.Request[order.GetTopSellersByRevenueRequest]) (*connect.Response[order.GetTopSellersByRevenueResponse], error)
	// 查詢近 N 天各店的成立訂單買家數、成立訂單數與賣家取消訂單數（單體 discovery 推薦排行用；
	// 以 store_id 升冪、keyset 分頁取全集）。成立訂單：已付款、未取消、未全額退款；以付款時間計。
	// 賣家取消以取消時間計。
	ListStoreOrderStats(context.Context, *connect.Request[order.ListStoreOrderStatsRequest]) (*connect.Response[order.ListStoreOrderStatsResponse], error)
	// 查詢單一店家在多個時間窗內的成立訂單數、不重複買家數與營收（單體賣家儀表板用）。成立訂單的定義與
	// ListStoreOrderStats 同一個（已付款、未取消、未全額退款，以付款時間計），營收是實付金額扣掉已退款的金額。
	GetStorePeriodOrderStats(context.Context, *connect.Request[order.GetStorePeriodOrderStatsRequest]) (*connect.Response[order.GetStorePeriodOrderStatsResponse], error)
	// ==================== Admin：撥款重發（收斂規範 §8.4 人工介入閉環）====================
	// 重新觸發既有 grant_payment_tasks 的執行；僅 Admin 可用。
	RetryGrant(context.Context, *connect.Request[order.RetryGrantRequest]) (*connect.Response[order.RetryGrantResponse], error)
	// ==================== §29 Admin 異常訂單列表 ====================
	// 跨服務異常訂單聚合（依 order.status 批次聚合 provider_* from Payment / Shipping）
	ListAbnormalOrdersForAdmin(context.Context, *connect.Request[order.ListAbnormalOrdersForAdminRequest]) (*connect.Response[order.ListAbnormalOrdersForAdminResponse], error)
	// ==== 服務間：CRM 訂單聚合 ====
	GetOrderAggregates(context.Context, *connect.Request[order.GetOrderAggregatesRequest]) (*connect.Response[order.GetOrderAggregatesResponse], error)
	// ==== 服務間：發票開立所需的訂單不可變快照（58 號 §7.1.2 步驟 5 ①）====
	// invoice-service 的 order.paid consumer 專用；唯讀、不改任何狀態。
	// 走 52 號 HMAC 內部授權四 header，client deadline 3s（58 號 §7.5「逾時矩陣」）。
	GetOrderInvoiceSnapshotInternal(context.Context, *connect.Request[order.GetOrderInvoiceSnapshotInternalRequest]) (*connect.Response[order.GetOrderInvoiceSnapshotInternalResponse], error)
	// ==== 服務間：買家於開立前更正發票資料（58 號 §6.2.5、B06／R03）====
	// order-service 是 snapshot_version 的唯一寫入者（58 號 I-50），invoice-service
	// 只能複製本 RPC 的回傳值、不得自行 +1。append-only：每次成功都 INSERT 一列新版本。
	// 走 52 號 HMAC 內部授權四 header。
	ReviseOrderInvoiceSnapshotInternal(context.Context, *connect.Request[order.ReviseOrderInvoiceSnapshotInternalRequest]) (*connect.Response[order.ReviseOrderInvoiceSnapshotInternalResponse], error)
	// ==================== Uber 即時報價中繼（66 §6.1.3；Stage 8B W2-2）====================
	//
	// 🔴 為什麼要經過 order-service 而不是 Gateway 直接打 shipping：
	//    報價需要「這一車的賣家是誰、每一件的尺寸重量單價是多少」，而那些是
	//    CheckoutService.resolveItems() 已經在做的事（批次打 product-service）。
	//    讓 Gateway 直接打 shipping 的話，那段解析要在 Gateway 重寫一份，
	//    而 Gateway 是 thin proxy、不該持有商品解析邏輯。
	//
	// ⚠️ 呼叫端只送 address_id 與 items：賣家由伺服端從 SKU 推導（66 §6.1.3 逐字
	//    「不收 externalStoreId」）。前端傳賣家 id 等於讓前端決定跟誰叫車。
	GetUberQuoteForCheckout(context.Context, *connect.Request[order.OrderUberQuoteRequest]) (*connect.Response[order.OrderUberQuoteResponse], error)
}

